// brown-noise-processor.js

/**
 * A processor that generates brown noise.
 * Brown noise is generated by a "random walk", where each sample is the previous sample
 * plus a small random value. This results in a power spectrum that decreases by 6dB per octave.
 */
class BrownNoiseProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.lastOut = 0.0;
  }

  process(inputs, outputs, parameters) {
    const output = outputs[0];
    output.forEach(channel => {
      for (let i = 0; i < channel.length; i++) {
        // Generate a random value between -1 and 1 (white noise)
        const white = Math.random() * 2 - 1;
        
        // The "random walk" formula to create brown noise from white noise
        const brown = (this.lastOut + (0.02 * white)) / 1.02;
        this.lastOut = brown;
        
        // Scale the output to a reasonable volume. This is an empirical value.
        channel[i] = brown * 3.5;
      }
    });
    // Return true to keep the processor alive.
    return true;
  }
}

registerProcessor('brown-noise-processor', BrownNoiseProcessor);
